import fuzzyHighlight from '@jetbrains/ring-ui-built/components/global/fuzzy-highlight'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import classNames from 'classnames'

import type {Match} from '../../../../common/Highlight/Highlight'
import Highlight from '../../../../common/Highlight/Highlight'
import {
  jobParameterSectionName,
  pipelineParameterSectionName,
} from '../../hooks/useParametersResolve'
import type {PipelineParametersResolve} from '../../services/pipelinesApi.types'

import styles from './HighlighterTextFieldItem.module.css'

export function getReslovedValueDescription(values: string[], type: string) {
  if (type === 'KNOWN_PASSWORD') {
    return '••••••'
  }

  if (!values?.length) {
    return 'no value'
  }

  return values?.join(',')
}

export function getParameterSuggestionItem(
  name: string,
  type: string,
  values: string[],
  matches: Match[],
) {
  return {
    compact: true,
    className: classNames(styles.dropdownListItem, styles.dropdownParameterListItem),
    key: name,
    leftNodes: (
      <div className={styles.dropdownListItemLabel}>
        <Highlight string={`%${name}%`} offset={-1} matches={matches} />
      </div>
    ),
    rightNodes: (
      <div className={styles.dropdownListItemDescription}>
        {getReslovedValueDescription(values, type)}
      </div>
    ),
  }
}

export function getValueSuggestionItem(name: string, matches: Match[]) {
  return {
    compact: true,
    className: styles.dropdownListItem,
    key: name,
    leftNodes: (
      <div className={styles.dropdownListItemLabel}>
        <Highlight string={name} offset={-1} matches={matches} />
      </div>
    ),
  }
}

export function getSuggestionList(
  parametersResolveGrouped: Map<string, PipelineParametersResolve[]>,
  line: string,
) {
  return Array.from(parametersResolveGrouped)
    .sort(([name]) => {
      if (name === jobParameterSectionName) {
        return -1
      } else if (name === pipelineParameterSectionName) {
        return 0
      }

      return 1
    })
    .reduce<SelectItem[]>((acc, [groupName, value]) => {
      const values = value.map(parameter => {
        const searchValue = line.substring(1)
        const {name, type, values} = parameter
        const fuzzySearch = searchValue != null ? fuzzyHighlight(searchValue, name) : null
        const matches = fuzzySearch ? fuzzySearch.matches : []

        return getParameterSuggestionItem(name, type, values, matches)
      })

      if (!groupName) {
        acc.unshift(...values)
      } else if (groupName) {
        acc.push(
          {
            compact: true,
            key: groupName,
            label: groupName,
            disabled: true,
            className: styles.dropdownGroupName,
          },
          ...values,
        )
      }

      return acc
    }, [])
}
