import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import List from '@jetbrains/ring-ui-built/components/list/list'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import type {SelectItem} from '@jetbrains/ring-ui-built/components/select/select'
import cn from 'classnames'
import React, {useCallback, useMemo} from 'react'

import useParametersResolve from '../../hooks/useParametersResolve'

import {getSuggestionList} from './HighlighterTextFieldItem.utils'
import HighlighterTextFieldItemHint from './HighlighterTextFieldItemHint'
import HighlighterTextFieldItemHintLoader from './HighlighterTextFieldItemHintLoader'

import styles from './HighlighterTextFieldItem.module.css'

type HighlighterTextFieldItemProps = {
  children: React.ReactElement
  line: string
  isElement: boolean
  isTyping?: boolean
  onSelect?: (item: SelectItem) => void
}

function HighlighterTextFieldItem({
  line,
  children,
  onSelect,
  isElement,
  isTyping = false,
}: HighlighterTextFieldItemProps) {
  const {
    parameterResolve,
    parametersResolveGrouped,
    isParametersResolveLoading,
    cancelParametersResolveHandler,
    loadSingleParameterResolve,
  } = useParametersResolve(line, isTyping)
  const suggestionList = useMemo(
    () => getSuggestionList(parametersResolveGrouped, line),
    [line, parametersResolveGrouped],
  )
  const dropdownMouseOverHandler = useCallback(() => {
    if (isElement && !isParametersResolveLoading) {
      loadSingleParameterResolve(line)
    }
  }, [isElement, isParametersResolveLoading, line, loadSingleParameterResolve])
  const dropdownMouseLeaveHandler = useCallback(() => {
    cancelParametersResolveHandler()
  }, [cancelParametersResolveHandler])
  const dropdownAnchor = useMemo(() => {
    if (isElement) {
      return React.cloneElement(children, {
        onMouseOver: dropdownMouseOverHandler,
        onMouseLeave: dropdownMouseLeaveHandler,
      })
    }

    return children
  }, [children, isElement, dropdownMouseOverHandler, dropdownMouseLeaveHandler])
  const isPopupShow = Boolean(
    isParametersResolveLoading || suggestionList.length || parameterResolve,
  )
  const popupClassNames = cn(styles.popup, {
    [styles.visibleHidden]: !isPopupShow,
    [styles.loaderInlinePopup]: isParametersResolveLoading,
  })

  return (
    <Dropdown
      className={styles.dropdown}
      hoverHideTimeOut={0}
      anchor={dropdownAnchor}
      initShown={isTyping}
      hoverMode={isElement}
    >
      <Popup
        autoFocusFirst
        trapFocus
        hidden={!isPopupShow}
        maxHeight="screen"
        className={popupClassNames}
      >
        {isParametersResolveLoading ? (
          <HighlighterTextFieldItemHintLoader />
        ) : isTyping ? (
          <List
            className={styles.suggestList}
            visible
            data={suggestionList}
            onSelect={onSelect}
            shortcuts
            compact
            activateFirstItem
            disableScrollToActive
            renderOptimization={false}
          />
        ) : (
          parameterResolve?.name && (
            <HighlighterTextFieldItemHint
              type={parameterResolve?.type}
              name={parameterResolve?.name}
              values={parameterResolve?.values}
            />
          )
        )}
      </Popup>
    </Dropdown>
  )
}

export default HighlighterTextFieldItem
