import deepEqual from 'fast-deep-equal'
import debounce from 'lodash/debounce'
import {useCallback, useEffect, useMemo, useState} from 'react'

import {useAppStore} from '../../../../hooks/react-redux'
import {useHighlighterTextFieldContext} from '../components/HighlighterTextField/HighlighterTextFieldContext'
import {getResolvedSettings} from '../EditPipelinePage/EditPipelinePage.selectors'
import useJobParametersStore from '../EditPipelinePage/SettingsSidebarContent/JobSettingsSidebar/JobParameters/useJobParametersStore'
import usePipelineParametersStore from '../EditPipelinePage/SettingsSidebarContent/PipelineSettingsSidebar/PipelineParameters/usePipelineParametersStore'
import {pipelinesApi} from '../services/pipelinesApi'
import type {PipelineParametersResolve} from '../services/pipelinesApi.types'

import {usePipelineId} from './pipeline'

const FETCH_DEBOUNCE_TIME = 500

const jobSelfParameterSectionName = ''
export const jobParameterSectionName = 'Job output parameters'
export const pipelineParameterSectionName = 'Pipeline parameters'
const otherParameters = 'Other parameters'

function useParametersResolve(searchText: string, isTyping: boolean) {
  const [isStartedLoading, setIsStartedLoading] = useState(false)
  const {renamedJobParameters} = useJobParametersStore()
  const {renamedParameters} = usePipelineParametersStore()
  const existingJobParametersKeys = useMemo(
    () => Object.values(renamedJobParameters ?? {}),
    [renamedJobParameters],
  )
  const existingParametersKeys = useMemo(
    () => Object.values(renamedParameters ?? {}),
    [renamedParameters],
  )
  const [
    fetchParametersResolve,
    {isParametersResolveLoading, parametersResolveRequestArgs, parametersResolve = []},
  ] = pipelinesApi.endpoints.getParametersResolve.useLazyQuery({
    selectFromResult: ({isFetching, isLoading, data, originalArgs}) => ({
      isParametersResolveLoading: isFetching || isLoading,
      parametersResolve: data,
      parametersResolveRequestArgs: originalArgs?.body,
    }),
  })
  const {getHighlightSpot} = useHighlighterTextFieldContext()
  const pipelineId = usePipelineId()
  const {getState} = useAppStore()
  const getPipelineDraftState = useCallback(
    () => getResolvedSettings(getState(), pipelineId),
    [getState, pipelineId],
  )
  const getPreparedSearchQuery = (value: string) => value.replace(/^%|%$/g, '')
  const loadParameterResolve = useCallback(
    async (search?: string, parameterName?: string) => {
      const pipelineDraftState = getPipelineDraftState()

      if (pipelineDraftState != null) {
        const spot = getHighlightSpot()

        await fetchParametersResolve({
          id: pipelineId,
          body: {
            pipeline: pipelineDraftState,
            scope: {
              search,
              parameterName,
              context: spot,
            },
          },
        })
      }

      setIsStartedLoading(false)
    },
    [fetchParametersResolve, getPipelineDraftState, pipelineId, getHighlightSpot],
  )
  const loadParametersResolveDebounce = useMemo(
    () => debounce(loadParameterResolve, FETCH_DEBOUNCE_TIME, {leading: false, trailing: true}),
    [loadParameterResolve],
  )
  const loadSingleParameterResolve = (value: string, force?: boolean) => {
    const pipelineResolveRequestArgs = parametersResolveRequestArgs?.pipeline
    const pipelineDraftState = getPipelineDraftState()
    const isEqualPipeline = deepEqual(pipelineResolveRequestArgs, pipelineDraftState)

    if (!isEqualPipeline || force) {
      const searchQuery = getPreparedSearchQuery(value)
      setIsStartedLoading(true)
      loadParameterResolve(undefined, searchQuery)
    }
  }
  const cancelParametersResolveHandler = () => {
    setIsStartedLoading(false)
  }
  const parametersResolveGrouped = useMemo(
    () =>
      parametersResolve.reduce<Map<string, PipelineParametersResolve[]>>((acc, parameter) => {
        const {name} = parameter
        const isJobSelfParameter = existingJobParametersKeys.includes(name)
        const isJobParameter = name.startsWith('job.')
        const isSettingsParameter = existingParametersKeys.includes(name)

        if (isJobSelfParameter) {
          acc.set(jobSelfParameterSectionName, [
            ...(acc.get(jobSelfParameterSectionName) ?? []),
            parameter,
          ])
        } else if (isJobParameter) {
          acc.set(jobParameterSectionName, [...(acc.get(jobParameterSectionName) ?? []), parameter])
        } else if (isSettingsParameter) {
          acc.set(pipelineParameterSectionName, [
            ...(acc.get(pipelineParameterSectionName) ?? []),
            parameter,
          ])
        } else {
          acc.set(otherParameters, [...(acc.get(otherParameters) ?? []), parameter])
        }

        return acc
      }, new Map()),
    [existingJobParametersKeys, existingParametersKeys, parametersResolve],
  )
  const parameterResolve = useMemo(() => {
    const [firstParamter] = parametersResolve

    if (isTyping || isParametersResolveLoading || isStartedLoading) {
      return null
    } else if (firstParamter) {
      return firstParamter
    }

    const {search, parameterName} = parametersResolveRequestArgs?.scope ?? {}
    const name = search ?? parameterName

    return {
      name,
      values: [],
      type: 'STRING',
    }
  }, [
    parametersResolve,
    isTyping,
    isParametersResolveLoading,
    isStartedLoading,
    parametersResolveRequestArgs?.scope,
  ])

  useEffect(() => {
    if (isTyping) {
      const searchQuery = getPreparedSearchQuery(searchText)
      setIsStartedLoading(true)
      loadParametersResolveDebounce(searchQuery)
    }

    return () => {
      setIsStartedLoading(false)
    }
  }, [isTyping, loadParametersResolveDebounce, pipelineId, searchText])

  return {
    parameterResolve,
    parametersResolve,
    parametersResolveGrouped,
    isParametersResolveLoading: isStartedLoading || isParametersResolveLoading,
    cancelParametersResolveHandler,
    loadSingleParameterResolve,
  }
}

export default useParametersResolve
