import {createContext, useCallback, useContext} from 'react'

import {useJobId} from '../../EditPipelinePage/EditPipelinePage.hooks'

import type {
  HighlighterTextFieldContextProps,
  HighlighterTextFieldProviderProps,
} from './HighlighterTextFieldContext.types'

const HighlighterTextFieldContext = createContext<HighlighterTextFieldContextProps>({})

export const useHighlighterTextFieldContext = () => {
  const jobId = useJobId() ?? undefined
  const {spot} = useContext(HighlighterTextFieldContext)
  const getHighlightSpot = useCallback(
    () => ({
      jobId,
      ...spot,
    }),
    [jobId, spot],
  )

  return {
    getHighlightSpot,
  }
}

function HighlighterTextFieldProvider({children, spot}: HighlighterTextFieldProviderProps) {
  const valueProvider = {
    spot,
  }
  return (
    <HighlighterTextFieldContext.Provider value={valueProvider}>
      {children}
    </HighlighterTextFieldContext.Provider>
  )
}

export default HighlighterTextFieldProvider
