import ListItem from '@jetbrains/ring-ui-built/components/list/list__item'
import {useMemo} from 'react'

import {noop} from '../../../../../utils/empty'

import {getReslovedValueDescription} from './HighlighterTextFieldItem.utils'

import styles from './HighlighterTextFieldItemHint.module.css'

type HighlighterTextFieldItemHintProps = {
  name?: string
  type?: string
  values?: string[]
}

function HighlighterTextFieldItemHint({
  name,
  type = '',
  values = [],
}: HighlighterTextFieldItemHintProps) {
  const description = useMemo(() => getReslovedValueDescription(values, type), [type, values])

  return (
    <ListItem
      hover={false}
      tabIndex={-1}
      scrolling={false}
      onMouseOver={noop}
      onClick={noop}
      leftNodes={
        <div className={styles.itemLabel}>
          <span className={styles.text}>{name}</span>
        </div>
      }
      rightNodes={<div className={styles.itemDescription}>{description}</div>}
      onCheckboxChange={noop}
      key={name}
      className={styles.item}
    />
  )
}

export default HighlighterTextFieldItemHint
