import {useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {getEmptyHash} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import {validateAllForms} from '../../../EditPipelinePage.actions'
import {getDraft, getPipeline, getPipelineErrorMessage} from '../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

import {settingsBlockId} from './PipelineParameters.consts'

function usePipelineParametersStore() {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const formSpotParamId = useMemo(() => ({pipelineId, type: FormType.PARAMETER}), [pipelineId])
  const formErrorSpotId = useMemo(() => ({pipelineId, formType: FormType.PARAMETER}), [pipelineId])
  const parameters: Record<string, string | undefined> =
    useAppSelector(state => getDraft(state, pipelineId)?.settings.parameters) ?? getEmptyHash()
  const parametersKeys = useMemo(() => Object.keys(parameters), [parameters])
  const parametersLength = parametersKeys.length
  const addParameterHandler = useCallback(() => {
    dispatch(pipelineDraft.actions.addParameter(pipelineId))
    dispatch(collapsedBlocks.actions.toggle({id: settingsBlockId, collapsed: false}))
  }, [dispatch, pipelineId])
  const deletedParameters = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.parameters,
    shallowEqual,
  )
  const renamedParameters = (useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.renamed?.parameters,
  ) ?? getEmptyHash()) as Record<string, string>
  const addedParameters = useAppSelector(state => getPipeline(state, pipelineId)?.added?.parameters)
  const parametersFormErrorMessage = useAppSelector(getPipelineErrorMessage(formErrorSpotId))
  const clearAddedParametersHandler = useCallback(() => {
    Object.keys(addedParameters ?? {}).forEach(key =>
      dispatch(pipelineErrors.actions.clear({...formErrorSpotId, formId: key})),
    )
    dispatch(pipelineDraft.actions.clearAddedParameters(pipelineId))
  }, [addedParameters, dispatch, formErrorSpotId, pipelineId])
  const getIsParametersValid = useCallback(
    () =>
      dispatch(
        validateAllForms(
          pipelineId,
          form => form.type === FormType.PARAMETER && addedParameters?.[form.id!] === true,
        ),
      ),
    [addedParameters, dispatch, pipelineId],
  )
  const parameterMultiplyConfirmHandler = useCallback(
    () => dispatch(pipelineDraft.actions.applyAddedParameters(pipelineId)),
    [dispatch, pipelineId],
  )
  const confirmParametersHandler = useCallback(
    (isValid: boolean, parameterName: string) => {
      if (isValid) {
        dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
      }
    },
    [dispatch, formSpotParamId],
  )
  const deleteParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(pipelineDraft.actions.deleteParameter({id: pipelineId, savedName: parameterName}))
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: parameterName,
        }),
      )
      dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
    },
    [dispatch, formErrorSpotId, formSpotParamId, pipelineId],
  )
  const restoreParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(pipelineDraft.actions.restoreParameter({id: pipelineId, savedName: parameterName}))
    },
    [dispatch, pipelineId],
  )
  const changeNameHandler = useCallback(
    (name: string, savedName: string) =>
      dispatch(
        pipelineDraft.actions.renameParameter({
          id: pipelineId,
          name,
          savedName,
        }),
      ),
    [dispatch, pipelineId],
  )
  const changeValueHandler = useCallback(
    (value: string, parameterName: string) =>
      dispatch(
        pipelineDraft.actions.setParameter({id: pipelineId, savedName: parameterName, value}),
      ),
    [dispatch, pipelineId],
  )
  const existingParameters = useMemo(
    () => parametersKeys.filter(parameter => !deletedParameters?.includes(parameter)),
    [deletedParameters, parametersKeys],
  )
  const existingParametersLength = existingParameters.length
  const summaryNote = useMemo(
    () =>
      parametersKeys
        .filter(key => !deletedParameters?.includes(key))
        .map(key => `${renamedParameters?.[key] ?? key}=${parameters[key]}`)
        .join(', '),
    [deletedParameters, parameters, parametersKeys, renamedParameters],
  )

  return {
    summaryNote,
    parameters,
    parametersKeys,
    parametersLength,
    deletedParameters,
    getIsParametersValid,
    addParameterHandler,
    existingParameters,
    existingParametersLength,
    parametersFormErrorMessage,
    parameterMultiplyConfirmHandler,
    clearAddedParametersHandler,

    formSpotParamId,
    formErrorSpotId,
    renamedParameters,
    changeNameHandler,
    changeValueHandler,
    confirmParametersHandler,
    deleteParametersHandler,
    restoreParametersHandler,
  }
}

export default usePipelineParametersStore
