import type {NormalizeTokens} from './Highlighter.types'

export const parameterResolveReferenceRegexp =
  /%(?!%)([a-zA-Z](?:[a-zA-Z0-9_.\-*]*|env\.[^ %\n]*|system\.[^ %\n]*)?)%/g
export const incompleteParameterResolveReferenceRegexp =
  /%(?!%)([a-zA-Z](?:[a-zA-Z0-9_.\-*]*|env\.[^ %\n]*|system\.[^ %\n]*)?)(?=\b|[^%]*$)/g

export function extractReferences(input: string): NormalizeTokens[] {
  const result: NormalizeTokens[] = []
  let lastIndex = 0

  input.replace(parameterResolveReferenceRegexp, (match: string, p1: unknown, offset: number) => {
    if (offset > lastIndex) {
      result.push({line: input.slice(lastIndex, offset)})
    }
    result.push({line: match, type: 'ref'})
    lastIndex = offset + match.length

    return match
  })

  if (lastIndex < input.length) {
    result.push({line: input.slice(lastIndex)})
  }

  return result.reduce<NormalizeTokens[]>((acc, token) => {
    const {type, line} = token
    const isClassNameRef = type === 'ref'

    if (!isClassNameRef && incompleteParameterResolveReferenceRegexp.test(token.line)) {
      const typingTokens = line.split(incompleteParameterResolveReferenceRegexp)
      const findTokensSet = new Set(
        line.match(incompleteParameterResolveReferenceRegexp)?.map(value => value.substring(1)),
      )

      typingTokens.forEach(newToken => {
        const isTypingRef = findTokensSet.has(newToken)
        acc.push({
          line: isTypingRef ? `%${newToken}` : newToken,
          type: findTokensSet.has(newToken) ? 'typing' : '',
        })
      })
    } else {
      acc.push(token)
    }

    return acc
  }, [])
}
