import {useCallback, useMemo} from 'react'
import {shallowEqual} from 'react-redux'

import {useAppDispatch, useAppSelector} from '../../../../../../../hooks/react-redux'
import {getEmptyHash} from '../../../../../../../utils/empty'
import {usePipelineId} from '../../../../hooks/pipeline'
import {validateAllForms} from '../../../EditPipelinePage.actions'
import {useJobId} from '../../../EditPipelinePage.hooks'
import {
  getDraftJobs,
  getPipeline,
  getPipelineErrorMessage,
} from '../../../EditPipelinePage.selectors'
import {
  collapsedBlocks,
  pipelineDraft,
  pipelineErrors,
  pipelineForm,
} from '../../../slices/EditPipelinePage.slices'
import {FormType} from '../../../slices/EditPipelinePage.slices.types'

import {jobParametersSettingsBlockId} from './JobParameters.consts'

function useJobParametersStore() {
  const pipelineId = usePipelineId()
  const jobId = useJobId() ?? ''
  const dispatch = useAppDispatch()
  const formSpotParamId = useMemo(
    () => ({
      jobId,
      pipelineId,
      type: FormType.JOB_PARAMETER,
    }),
    [jobId, pipelineId],
  )
  const formErrorSpotId = useMemo(
    () => ({
      jobId,
      pipelineId,
      formType: FormType.JOB_PARAMETER,
    }),
    [jobId, pipelineId],
  )
  const jobParameters =
    useAppSelector(state => getDraftJobs(state, pipelineId)?.[jobId]?.parameters) ?? getEmptyHash()
  const jobParametersKeys = useMemo(() => Object.keys(jobParameters), [jobParameters])
  const jobParametersLength = jobParametersKeys.length
  const addJobParameterHandler = useCallback(
    (prefix?: string) => {
      dispatch(pipelineDraft.actions.addJobParameter({pipelineId, jobId, prefix}))
      dispatch(collapsedBlocks.actions.toggle({id: jobParametersSettingsBlockId, collapsed: false}))
    },
    [dispatch, jobId, pipelineId],
  )
  const deletedJobParameters = useAppSelector(
    state => getPipeline(state, pipelineId)?.deleted?.jobParameters,
    shallowEqual,
  )
  const addedJobParameters = useAppSelector(
    state => getPipeline(state, pipelineId)?.added?.jobParameters,
  )
  const jobParametersFormErrorMessage = useAppSelector(getPipelineErrorMessage(formErrorSpotId))
  const clearAddedJobParametersHandler = useCallback(() => {
    Object.keys(addedJobParameters ?? {}).forEach(key =>
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: key,
        }),
      ),
    )
    dispatch(pipelineDraft.actions.clearAddedJobParameters({pipelineId, jobId}))
  }, [addedJobParameters, dispatch, formErrorSpotId, jobId, pipelineId])
  const getIsJobParametersValid = useCallback(
    () =>
      dispatch(
        validateAllForms(
          pipelineId,
          form =>
            form.type === FormType.JOB_PARAMETER &&
            form.jobId === jobId &&
            addedJobParameters?.[form.id!] === true,
        ),
      ),
    [addedJobParameters, dispatch, jobId, pipelineId],
  )
  const jobParameterMultiplyConfirmHandler = useCallback(
    () => dispatch(pipelineDraft.actions.applyAddedJobParameters(pipelineId)),
    [dispatch, pipelineId],
  )
  const confirmParametersHandler = useCallback(
    (isValid: boolean, parameterName: string) => {
      if (isValid) {
        dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
      }
    },
    [dispatch, formSpotParamId],
  )
  const deleteParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(
        pipelineDraft.actions.deleteJobParameter({pipelineId, jobId, savedName: parameterName}),
      )
      dispatch(
        pipelineErrors.actions.clear({
          ...formErrorSpotId,
          formId: parameterName,
        }),
      )
      dispatch(pipelineForm.actions.close({...formSpotParamId, id: parameterName}))
    },
    [dispatch, formErrorSpotId, formSpotParamId, jobId, pipelineId],
  )
  const restoreParametersHandler = useCallback(
    (parameterName: string) => {
      dispatch(
        pipelineDraft.actions.restoreJobParameter({pipelineId, jobId, savedName: parameterName}),
      )
    },
    [dispatch, jobId, pipelineId],
  )
  const changeNameHandler = useCallback(
    (name: string, savedName: string) => {
      dispatch(
        pipelineDraft.actions.renameJobParameter({
          pipelineId,
          name,
          savedName,
        }),
      )
    },
    [dispatch, pipelineId],
  )
  const changeValueHandler = useCallback(
    (value: string, parameterName: string) => {
      dispatch(
        pipelineDraft.actions.setJobParameter({pipelineId, jobId, savedName: parameterName, value}),
      )
    },
    [dispatch, jobId, pipelineId],
  )
  const renamedJobParameters = (useAppSelector(
    state => state.pipelines.pipelineDraft[pipelineId]?.renamed?.jobParameters,
  ) ?? getEmptyHash()) as Record<string, string>
  const existingJobParameters = useMemo(
    () => jobParametersKeys.filter(jobParameter => !deletedJobParameters?.includes(jobParameter)),
    [deletedJobParameters, jobParametersKeys],
  )
  const existingJobParametersLength = existingJobParameters.length

  return {
    jobParameters,
    jobParametersKeys,
    jobParametersLength,
    deletedJobParameters,
    getIsJobParametersValid,
    addJobParameterHandler,
    existingJobParametersLength,
    jobParametersFormErrorMessage,
    jobParameterMultiplyConfirmHandler,
    clearAddedJobParametersHandler,
    formSpotParamId,
    formErrorSpotId,
    renamedJobParameters,
    changeNameHandler,
    changeValueHandler,
    confirmParametersHandler,
    deleteParametersHandler,
    restoreParametersHandler,
  }
}

export default useJobParametersStore
